def semver_sort(versions):
    def parse(v):
        main_part = v
        build = None
        if '+' in v:
            main_part, build = v.split('+', 1)
        prerelease = None
        if '-' in main_part:
            core, prerelease = main_part.split('-', 1)
        else:
            core = main_part
        major, minor, patch = core.split('.')
        major, minor, patch = int(major), int(minor), int(patch)
        if prerelease is not None:
            has_pre = 0  # sorts before no prerelease
            idents = prerelease.split('.')
            pre_key = []
            for ident in idents:
                if ident.isdigit():
                    pre_key.append((0, int(ident)))
                else:
                    pre_key.append((1, ident))
        else:
            has_pre = 1
            pre_key = []
        return (major, minor, patch, has_pre, pre_key)

    return sorted(versions, key=parse)

